select tab_date::text||'|'||batch k, count(*)||' rows meals '||count(*) filter(where base='meals')||' hh '||coalesce(sum(hh) filter(where base='meals'),0)||' | box '||count(*) filter(where base='box')||' hh '||coalesce(sum(hh) filter(where base='box'),0)||' enh '||coalesce(sum(enh),0) v from billing_import where company='CCS' and tab_date>='2026-11-03' group by tab_date,batch order by 1
